 1| /**
 2|  * standard-shipping: the shipping charge for an order that does not ship free.
 3|  *
 4|  * The rule: a base fee plus a charge per kilogram; express costs twice that.
 5|  * Rounded to the cent.
 6|  * Example: 2 kg, standard → 4.95 + 0.85 × 2 = `shipping = 6.65`.
 7|  */
 8| import { roundCents } from '../../money.mjs';
