10| export const purpose = 'Charge the base fee plus a rate per kilogram (double for express).';
11| 
12| /** The fee every shipped order pays. */
13| const BASE_FEE = 4.95;
14| /** The charge for each kilogram the order weighs. */
15| const PER_KG = 0.85;
16| /** How much more express costs than standard. */
17| const EXPRESS_FACTOR = 2;
18| 
19| /** @param {any} scope */
20| export function run(scope) {
21|   const fee = BASE_FEE + PER_KG * scope.totalWeight;
22|   scope.shipping = roundCents(scope.shipMethod === 'express' ? fee * EXPRESS_FACTOR : fee);
